package com.rezoxnemesis.videostudio;

import android.content.Context;
import android.graphics.Bitmap;
import android.graphics.Color;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.RuntimeEnvironment;
import org.robolectric.annotation.Config;
import org.robolectric.annotation.GraphicsMode;
import java.io.File;
import java.io.FileOutputStream;
import java.nio.file.Files;
import java.nio.charset.StandardCharsets;
import java.util.UUID;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class)
@Config(sdk=33,manifest=Config.NONE)
@GraphicsMode(GraphicsMode.Mode.NATIVE)
public final class SketchPaintStoreTest {
    final Context context=RuntimeEnvironment.getApplication();
    JSONObject doc(String id,int size)throws Exception {return SketchDocument.create(new JSONObject().put("sketchId",id).put("width",size).put("height",size).put("frameCount",1).put("background","#00000000"));}
    void cel(JSONObject doc,JSONObject descriptor)throws Exception {doc.getJSONArray("layers").getJSONObject(0).getJSONArray("objects").put(SketchEditOps.completeObject(new JSONObject().put("id","cel").put("kind","paint").put("paint",descriptor).put("bounds",new JSONObject().put("x",0).put("y",0).put("width",1).put("height",1))));}
    JSONObject stroke(double y,double size)throws Exception {return new JSONObject().put("type","paint_stroke").put("objectId","cel").put("strokeId",UUID.randomUUID().toString()).put("points",new JSONArray().put(new JSONArray().put(.1).put(y).put(1)).put(new JSONArray().put(.9).put(y).put(1))).put("brush",new JSONObject().put("mode","paint").put("color","#FFFF5522").put("sizePx",size));}
    String guide(JSONObject doc)throws Exception {Bitmap source=Bitmap.createBitmap(64,64,Bitmap.Config.ARGB_8888);for(int y=0;y<64;y++)for(int x=0;x<64;x++)source.setPixel(x,y,((x/2)%2)==0?Color.RED:Color.BLUE);File root=new File(context.getFilesDir(),"sketch_studio/"+doc.getString("id")+"/references");assertTrue(root.mkdirs());File temp=new File(root,"source.png");try(FileOutputStream out=new FileOutputStream(temp)){source.compress(Bitmap.CompressFormat.PNG,100,out);}finally{source.recycle();}String hash=SketchProjectStore.fileHash(temp);assertTrue(temp.renameTo(new File(root,hash+".png")));JSONObject ref=new JSONObject().put("file",hash+".png").put("sha256",hash).put("width",64).put("height",64).put("sourceProjectId","synthetic").put("sourceAssetId","test");doc.getJSONArray("layers").getJSONObject(0).getJSONArray("objects").put(SketchEditOps.completeObject(new JSONObject().put("id","guide").put("kind","image").put("reference",ref).put("bounds",new JSONObject().put("x",0).put("y",0).put("width",1).put("height",1)).put("transform",SketchDocument.transform().put("opacity",0))));return hash;}
    @Test public void strokeAcrossTileSeamPublishesImmutablePixelsWithoutChangingInputDocument()throws Exception {
        String id=UUID.randomUUID().toString();try(SketchPaintStore store=new SketchPaintStore(context,id)){JSONObject d=doc(id,512);JSONObject empty=store.empty(512,512);cel(d,empty);String original=d.toString();SketchPaintStore.PreparedChange result=store.prepare(d,stroke(.5,16));assertEquals(original,d.toString());assertNotEquals(empty.getString("sha256"),result.descriptor.getString("sha256"));assertTrue(result.dirtyTileCount>=2);store.verify(result.descriptor);Bitmap after=store.render(result.descriptor,512,null),before=store.render(empty,512,null);try{assertEquals(0,before.getPixel(256,256));assertEquals(after.getPixel(255,256),after.getPixel(256,256));assertEquals(Color.rgb(255,85,34),after.getPixel(256,256));}finally{after.recycle();before.recycle();}}
    }
    @Test public void visiblePrefixStartsBlankDrawsInOrderAndEndsAtDurablePixels()throws Exception {
        String id=UUID.randomUUID().toString();try(SketchPaintStore store=new SketchPaintStore(context,id)){JSONObject d=doc(id,512);cel(d,store.empty(512,512));SketchPaintStore.PreparedChange result=store.prepare(d,stroke(.5,16));Bitmap a=store.renderPrefix(result.visualOperation,0,512,null),b=store.renderPrefix(result.visualOperation,.3,512,null),c=store.renderPrefix(result.visualOperation,1,512,null),finalImage=store.render(result.descriptor,512,null);try{assertEquals(0,a.getPixel(100,256));assertTrue(Color.alpha(b.getPixel(100,256))>0);assertEquals(0,b.getPixel(450,256));assertTrue(c.sameAs(finalImage));assertEquals(1,store.journal(result.descriptor,0,16).length());}finally{a.recycle();b.recycle();c.recycle();finalImage.recycle();}}
    }
    @Test public void cloneSamplesFineTextureOnlyUnderBrushAndSurvivesGuideRemoval()throws Exception {
        String id=UUID.randomUUID().toString();try(SketchPaintStore store=new SketchPaintStore(context,id)){JSONObject d=doc(id,512);cel(d,store.empty(512,512));String sha=guide(d);JSONObject op=stroke(.5,32);op.getJSONObject("brush").put("mode","clone");op.put("cloneSource",new JSONObject().put("objectId","guide").put("sha256",sha));SketchPaintStore.PreparedChange result=store.prepare(d,op);assertEquals(sha,SketchProjectStore.fileHash(new File(context.getFilesDir(),"sketch_studio/"+id+"/references/"+sha+".png")));Bitmap image=store.render(result.descriptor,512,null);try{assertEquals(Color.RED,image.getPixel(128,256));assertEquals(Color.BLUE,image.getPixel(144,256));assertEquals(0,image.getPixel(128,100));assertEquals("#FFFF0000",store.sampleReference(d,"guide",sha,.25,.5,0));}finally{image.recycle();}assertTrue(new File(context.getFilesDir(),"sketch_studio/"+id+"/references/"+sha+".png").delete());Bitmap replay=store.renderPrefix(result.visualOperation,1,512,null);try{assertEquals(Color.RED,replay.getPixel(128,256));}finally{replay.recycle();}assertTrue(store.dependencies(result.descriptor).keySet().stream().anyMatch(p->p.startsWith("paint/sources/")));}
    }
    @Test public void affineCloneMappingChangesSampledAppearanceAndRejectsUnownedOrChangedSource()throws Exception {
        String id=UUID.randomUUID().toString();try(SketchPaintStore store=new SketchPaintStore(context,id)){JSONObject d=doc(id,512);cel(d,store.empty(512,512));String sha=guide(d);JSONObject op=stroke(.5,32);op.getJSONObject("brush").put("mode","clone");op.put("cloneSource",new JSONObject().put("objectId","guide").put("sha256",sha).put("mapping",new JSONArray().put(1).put(0).put(0).put(1).put(.03125).put(0)));SketchPaintStore.PreparedChange change=store.prepare(d,op);Bitmap image=store.render(change.descriptor,512,null);try{assertEquals(Color.BLUE,image.getPixel(128,256));}finally{image.recycle();}op.getJSONObject("cloneSource").put("sha256","0".repeat(64));assertThrows(Exception.class,()->store.prepare(d,op));op.getJSONObject("cloneSource").put("objectId","not_owned").put("sha256",sha);assertThrows(Exception.class,()->store.prepare(d,op));}
    }
    @Test public void dependenciesAreCopiedToAnotherOwnerAndCorruptedTilesAreRejected()throws Exception {
        String id=UUID.randomUUID().toString(),target=UUID.randomUUID().toString();try(SketchPaintStore store=new SketchPaintStore(context,id)){JSONObject d=doc(id,512);cel(d,store.empty(512,512));SketchPaintStore.PreparedChange result=store.prepare(d,stroke(.5,12));store.copyTo(target,result.descriptor);try(SketchPaintStore copy=new SketchPaintStore(context,target)){copy.verify(result.descriptor);assertEquals("#FFFF5522",copy.sample(result.descriptor,.5,.5));}File tile=store.dependencies(result.descriptor).entrySet().stream().filter(e->e.getKey().startsWith("paint/tiles/")).findFirst().get().getValue();Files.write(tile.toPath(),new byte[]{1,2,3});assertThrows(Exception.class,()->store.verify(result.descriptor));}
    }
    @Test public void blockedAssetStorageLeavesPreviousDescriptorReadableAndRejectsUnsafeDescriptors()throws Exception {
        String id=UUID.randomUUID().toString();try(SketchPaintStore store=new SketchPaintStore(context,id)){JSONObject d=doc(id,512),empty=store.empty(512,512);cel(d,empty);File path=new File(context.getFilesDir(),"sketch_studio/"+id+"/paint/tiles");if(path.isDirectory())assertTrue(path.delete());assertTrue(path.createNewFile());assertThrows(Exception.class,()->store.prepare(d,stroke(.5,16)));assertEquals("#00000000",store.sample(empty,.5,.5));JSONObject unsafe=new JSONObject(empty.toString()).put("file","../foreign.json");assertThrows(Exception.class,()->SketchPaintStore.validateDescriptor(unsafe));}
    }
    @Test public void cropRenderingIsBoundedToRequestedViewport()throws Exception {
        String id=UUID.randomUUID().toString();try(SketchPaintStore store=new SketchPaintStore(context,id)){JSONObject d=doc(id,512);cel(d,store.empty(512,512));SketchPaintStore.PreparedChange change=store.prepare(d,stroke(.5,12));Bitmap viewport=store.render(change.descriptor,256,new JSONObject().put("x",.4).put("y",.4).put("width",.2).put("height",.2));try{assertEquals(256,viewport.getWidth());assertEquals(256,viewport.getHeight());assertTrue(Color.alpha(viewport.getPixel(128,128))>0);}finally{viewport.recycle();}}
    }
    @Test public void defaultCloneCannotPaintOutsideTheVisibleCroppedGuideDomain()throws Exception {
        String id=UUID.randomUUID().toString();try(SketchPaintStore store=new SketchPaintStore(context,id)){JSONObject d=doc(id,512);cel(d,store.empty(512,512));String sha=guide(d);JSONObject guide=SketchDocument.object(d,"guide"),area=new JSONObject().put("x",.25).put("y",.25).put("width",.5).put("height",.5);guide.put("bounds",area).put("referenceCrop",new JSONObject(area.toString()));JSONObject op=stroke(.5,32);op.getJSONObject("brush").put("mode","clone");op.put("cloneSource",new JSONObject().put("objectId","guide").put("sha256",sha));SketchPaintStore.PreparedChange change=store.prepare(d,op);Bitmap image=store.render(change.descriptor,512,null);try{assertEquals("Pixels outside the guide crop must remain transparent",0,image.getPixel(100,256));assertEquals(Color.RED,image.getPixel(256,256));}finally{image.recycle();}}
    }
    @Test public void referenceEyedropperReturnsTransparentOutsideItsCroppedGuideBounds()throws Exception {
        String id=UUID.randomUUID().toString();try(SketchPaintStore store=new SketchPaintStore(context,id)){JSONObject d=doc(id,512);cel(d,store.empty(512,512));String sha=guide(d);JSONObject guide=SketchDocument.object(d,"guide"),area=new JSONObject().put("x",.25).put("y",.25).put("width",.5).put("height",.5);guide.put("bounds",area).put("referenceCrop",new JSONObject(area.toString()));assertEquals("#00000000",store.sampleReference(d,"guide",sha,.15,.5,0));assertEquals("#FFFF0000",store.sampleReference(d,"guide",sha,.5,.5,0));}
    }
    JSONObject altered(JSONObject original,JSONObject record,JSONObject manifest,File paintRoot)throws Exception {
        byte[] journal=SketchDocument.canonical(record).getBytes(StandardCharsets.UTF_8);String strokeSha=SketchDocument.sha256(journal);Files.write(new File(new File(paintRoot,"strokes"),strokeSha+".json").toPath(),journal);manifest.put("strokeSha256",strokeSha);byte[] snapshot=SketchDocument.canonical(manifest).getBytes(StandardCharsets.UTF_8);String sha=SketchDocument.sha256(snapshot);Files.write(new File(paintRoot,sha+".json").toPath(),snapshot);return new JSONObject(original.toString()).put("file",sha+".json").put("sha256",sha);
    }
    @Test public void hashConsistentJournalCannotClaimOneCloneSourceAndReplayAnother()throws Exception {
        String id=UUID.randomUUID().toString();try(SketchPaintStore store=new SketchPaintStore(context,id)){JSONObject d=doc(id,512);cel(d,store.empty(512,512));String sourceSha=guide(d);JSONObject op=stroke(.5,32);op.getJSONObject("brush").put("mode","clone");op.put("cloneSource",new JSONObject().put("objectId","guide").put("sha256",sourceSha));SketchPaintStore.PreparedChange change=store.prepare(d,op);File root=new File(context.getFilesDir(),"sketch_studio/"+id+"/paint");Bitmap replacement=Bitmap.createBitmap(64,64,Bitmap.Config.ARGB_8888);replacement.eraseColor(Color.GREEN);File temporary=new File(root,"replacement.png");try(FileOutputStream stream=new FileOutputStream(temporary)){replacement.compress(Bitmap.CompressFormat.PNG,100,stream);}finally{replacement.recycle();}String replacementSha=SketchProjectStore.fileHash(temporary);assertTrue(temporary.renameTo(new File(new File(root,"sources"),replacementSha+".png")));JSONObject record=new JSONObject(change.visualOperation.getJSONObject("stroke").toString());record.getJSONObject("source").put("file",replacementSha+".png").put("sha256",replacementSha);JSONObject manifest=new JSONObject(new String(Files.readAllBytes(new File(root,change.descriptor.getString("file")).toPath()),StandardCharsets.UTF_8));JSONObject forged=altered(change.descriptor,record,manifest,root);assertThrows(Exception.class,()->store.verify(forged));}
    }
    @Test public void hashConsistentHistoryCannotChangeCanvasDimensionsAcrossParentSnapshots()throws Exception {
        String id=UUID.randomUUID().toString();try(SketchPaintStore store=new SketchPaintStore(context,id)){JSONObject d=doc(id,512);cel(d,store.empty(512,512));SketchPaintStore.PreparedChange change=store.prepare(d,stroke(.5,16));File root=new File(context.getFilesDir(),"sketch_studio/"+id+"/paint");JSONObject parent=store.empty(256,256),record=new JSONObject(change.visualOperation.getJSONObject("stroke").toString());record.put("beforePaint",parent);JSONObject manifest=new JSONObject(new String(Files.readAllBytes(new File(root,change.descriptor.getString("file")).toPath()),StandardCharsets.UTF_8)).put("parentSha256",parent.getString("sha256"));JSONObject forged=altered(change.descriptor,record,manifest,root);assertThrows(Exception.class,()->store.dependencies(forged));}
    }
    @Test public void deeplyNestedHashConsistentSnapshotIsRejectedBeforeRecursiveJsonParsing()throws Exception {
        String id=UUID.randomUUID().toString();try(SketchPaintStore store=new SketchPaintStore(context,id)){JSONObject descriptor=store.empty(256,256);StringBuilder json=new StringBuilder("{\"schema\":\"videostudio.sketch.paint.snapshot.v1\",\"width\":256,\"height\":256,\"tileSize\":256,\"strokeCount\":0,\"tiles\":");for(int i=0;i<2048;i++)json.append('[');for(int i=0;i<2048;i++)json.append(']');json.append('}');byte[] bytes=json.toString().getBytes(StandardCharsets.UTF_8);String sha=SketchDocument.sha256(bytes);File root=new File(context.getFilesDir(),"sketch_studio/"+id+"/paint");Files.write(new File(root,sha+".json").toPath(),bytes);JSONObject forged=new JSONObject(descriptor.toString()).put("file",sha+".json").put("sha256",sha);Throwable error=assertThrows(Throwable.class,()->store.verify(forged));assertTrue("Depth guard must reject before parser recursion",error instanceof IllegalArgumentException);String message=error.getMessage().toLowerCase(java.util.Locale.ROOT);assertTrue(message.contains("depth")||message.contains("nesting"));}
    }
    @Test public void clonePinsSelectedFrameGuideTransformRatherThanCelStart()throws Exception {
        String id=UUID.randomUUID().toString();try(SketchPaintStore store=new SketchPaintStore(context,id)){JSONObject d=doc(id,512);d.put("frameCount",6);cel(d,store.empty(512,512));SketchDocument.object(d,"cel").put("exposure",6);String sha=guide(d);JSONObject guide=SketchDocument.object(d,"guide");guide.put("exposure",6).put("keys",new JSONArray().put(new JSONObject().put("frame",5).put("interpolation","hold").put("transform",SketchDocument.transform().put("rotation",90).put("x",.03125))));JSONObject start=stroke(.5,32);start.getJSONObject("brush").put("mode","clone");start.put("cloneSource",new JSONObject().put("objectId","guide").put("sha256",sha));SketchPaintStore.PreparedChange first=store.prepare(d,start);JSONObject later=stroke(.5,32).put("frameIndex",5);later.getJSONObject("brush").put("mode","clone");later.put("cloneSource",new JSONObject().put("objectId","guide").put("sha256",sha));SketchPaintStore.PreparedChange fifth=store.prepare(d,later);Bitmap a=store.render(first.descriptor,512,null),b=store.render(fifth.descriptor,512,null);try{assertEquals(Color.BLUE,a.getPixel(144,256));assertEquals(Color.RED,b.getPixel(144,256));assertEquals("#FFFF0000",store.sampleReference(d,"guide",sha,144.5/512,.5,5));}finally{a.recycle();b.recycle();}}
    }
    int files(File directory){int count=0;File[] entries=directory.listFiles();if(entries!=null)for(File entry:entries)count+=entry.isDirectory()?files(entry):1;return count;}
    @Test public void humanCloneGesturePreviewUsesActualTextureWithoutPublishingDrawingAssets()throws Exception {
        String id=UUID.randomUUID().toString();try(SketchPaintStore store=new SketchPaintStore(context,id)){JSONObject d=doc(id,512);cel(d,store.empty(512,512));String sha=guide(d),original=d.toString();File paint=new File(context.getFilesDir(),"sketch_studio/"+id+"/paint");int count=files(paint);JSONObject op=stroke(.5,32);op.getJSONObject("brush").put("mode","clone");op.put("cloneSource",new JSONObject().put("objectId","guide").put("sha256",sha));Bitmap image=store.renderGesture(d,op,512,null);try{assertEquals(Color.RED,image.getPixel(128,256));assertEquals(Color.BLUE,image.getPixel(144,256));assertEquals(0,image.getPixel(128,100));assertEquals(count,files(paint));assertEquals(original,d.toString());}finally{image.recycle();}}
    }
    @Test public void humanEraseGesturePreviewRemovesPixelsOnlyInsideTheSelectedCelClip()throws Exception {
        String id=UUID.randomUUID().toString();try(SketchPaintStore store=new SketchPaintStore(context,id)){JSONObject d=doc(id,512);cel(d,store.empty(512,512));SketchPaintStore.PreparedChange change=store.prepare(d,stroke(.5,24));SketchDocument.object(d,"cel").put("paint",change.descriptor);File paint=new File(context.getFilesDir(),"sketch_studio/"+id+"/paint");int count=files(paint);JSONObject op=stroke(.5,16);op.getJSONObject("brush").put("mode","erase");op.put("clip",new JSONObject().put("x",.45).put("y",.4).put("width",.1).put("height",.2));Bitmap image=store.renderGesture(d,op,512,null);try{assertEquals(0,image.getPixel(256,256));assertEquals(Color.rgb(255,85,34),image.getPixel(128,256));assertEquals(count,files(paint));}finally{image.recycle();}}
    }
}
